'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E = escapeHTML;
const states = {FREE:'사용 가능',RESERVED_IDLE:'예약 · 대여 가능',RESERVED_IN_USE:'예약 · 사용 중',UNRESERVED_IN_USE:'예약 없이 사용 중',BORROWED:'다른 사용자 대여 중',CONFLICT:'사용 조정 필요',OFFLINE:'오프라인',UNKNOWN:'확인 필요'};
const stateHelp = {FREE:'예약이 없고, 프로세스·VRAM·최근 10분 사용률이 유휴 상태입니다.',RESERVED_IDLE:'예약자가 우선 사용합니다. 임시 사용 시 예약자의 요청에 맞춰 반납하세요.',RESERVED_IN_USE:'예약자와 실제 GPU 사용자가 일치합니다.',UNRESERVED_IN_USE:'예약 없이 작업이 실행 중입니다. 실제 사용자에게 먼저 확인하세요.',BORROWED:'예약자와 다른 사용자가 작업 중입니다. 예약자의 사용 계획을 확인하세요.',CONFLICT:'여러 예약 또는 예약자·다른 사용자의 프로세스가 겹칩니다. 사용자 간 조정이 필요합니다.',OFFLINE:'최근 GPU 메트릭이 없습니다. 서버·exporter·네트워크를 확인하세요.',UNKNOWN:'예약 또는 사용 정보를 충분히 확인할 수 없습니다. 사용 가능 여부를 직접 확인하세요.'};
const titles = {overview:['연구 자원 현황','대시보드'],reservations:['예약 시간','예약 캘린더'],monitoring:['사용량 추이','사용량 모니터링'],storage:['저장공간','저장공간'],reports:['운영 리포트','운영 리포트'],mine:['내 예약','내 예약'],remote:['원격 접속','원격 접속'],accounts:['계정 연결','계정 연결'],guide:['이용 가이드','이용 가이드'],news:['연구 뉴스','연구 뉴스']};
let snapshot = null, history = null, historyError = '', page = 'overview', serverFilter='all', stateFilter='all', query='', period=24, refreshBusy=false;
let selectedDate = kstDate(new Date()), historyKey=0;
let statistics=null, statisticsError='';
let report=null, reportError='', reportDays=7, reportKey=0;
let session=null, authTab='login';
let storage=null, storageError='', accounts=null, accountsError='', news=null, newsError='', newsOpen=null, newsRegion='world';
const NO_MONITORING='모니터링(Prometheus)을 연결하면 표시됩니다.';
const REFRESH_MS=10000, TREND_MS=60000, REFRESH_LABEL=`${REFRESH_MS/1000}초마다`;
function kstDate(d) {return new Date(d.getTime()+9*3600000).toISOString().slice(0,10);}
function kstInput(d) {return new Date(d.getTime()+9*3600000).toISOString().slice(0,16);}
function time(v) {return new Date(v).toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false});}
function date(v) {return new Date(v).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',month:'short',day:'numeric'});}
function num(v, digits=0) {return v == null || !Number.isFinite(+v) ? '—' : (+v).toFixed(digits);}
function offlineIsNotConfigured() {return snapshot&&snapshot.monitoring===false;}
function stateLabel(state) {return offlineIsNotConfigured()&&state==='OFFLINE'?'모니터링 미연동':(states[state]||state);}
function stateNote(state) {return offlineIsNotConfigured()&&state==='OFFLINE'?'모니터링을 연결하면 실제 사용 상태가 표시됩니다. 예약은 지금도 정상 동작합니다.':stateHelp[state];}
function badge(state) {return `<span class="badge ${E(state)}">${E(stateLabel(state))}</span>`;}
function percent(v) {return v == null ? '—' : `${num(v)}%`;}
function toast(message) {$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4000);}
async function api(path, options={}) {const res=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});if(!res.ok){let body={};try{body=await res.json();}catch{}const detail=body.detail;const error=new Error(typeof detail==='string'?detail:Array.isArray(detail)?detail.map(d=>d.msg.replace('Value error, ','')).join(' / '):'요청을 처리하지 못했습니다. 잠시 후 다시 시도하세요.');error.status=res.status;throw error;}return res.status===204?null:res.json();}
function me_() {return me();}
function me() {return snapshot?.current_user||session?.user||null;}
function canManage(r) {const user=me();return snapshot.mode!=='live'&&!!user&&(user.role==='admin'||r.owner_linux===user.username);}
function visibleGPUs() {return snapshot.gpus.filter(g=>(serverFilter==='all'||g.server===serverFilter)&&(stateFilter==='all'||g.state===stateFilter)&&(`${g.id} ${g.model} ${g.reservation?.owner_name||''}`.toLowerCase().includes(query.toLowerCase())));}
function meter(label,value,text,cls='') {return `<div class="meter-label"><span>${E(label)}</span><b>${E(text)}</b></div><div class="bar ${cls}"><i style="width:${Math.max(0,Math.min(100,value||0))}%"></i></div>`;}
function gpuCard(g) {const m=g.metrics,r=g.reservation;return `<button class="gpu-card" data-gpu="${E(g.id)}" aria-label="${E(g.id)} ${E(stateLabel(g.state))} 상세"><div class="gpu-top"><span class="gpu-id">${E(g.id)}</span><span class="gpu-chip">▦</span></div><div class="gpu-model">${E(g.model)} · ${E(g.vram_gb)} GB</div>${badge(g.state)}<div class="gpu-person">${r?`<strong>${E(r.owner_name||r.owner_linux||'예약자')}</strong> <span>· ${time(r.end)}까지</span>`:g.state==='FREE'?'<span class="available">누구나 사용 가능</span>':`실사용 <strong>${E((m.processes||[]).map(p=>p.user).filter((v,i,a)=>a.indexOf(v)===i).join(', ')||'확인 필요')}</strong>`}</div>${meter('GPU 사용률',m.util,percent(m.util))}${meter('VRAM',m.vram_total_mib?m.vram_used_mib/m.vram_total_mib*100:0,`${num(m.vram_used_mib==null?null:m.vram_used_mib/1024,1)} / ${num(m.vram_total_mib==null?null:m.vram_total_mib/1024)} GB`,'vram')}<div class="gpu-bottom"><span>♨ ${num(m.temperature)}°C <span style="margin-left:8px">ϟ ${num(m.power)} W</span></span><span class="${['FREE','RESERVED_IDLE'].includes(g.state)?'free-label':''}">${g.state==='RESERVED_IDLE'?'Borrowable ↗':'상세 보기 ↗'}</span></div></button>`;}
function serverCards() {const gpus=visibleGPUs();return snapshot.servers.map(s=>{const list=gpus.filter(g=>g.server===s.id);if(!list.length)return '';return `<section class="server"><div class="server-head"><span class="server-icon">▤</span><div class="server-title">${E(s.name)}<small>${E(s.id)}</small></div><span class="server-online ${s.online?'':'offline'}">● ${s.online?'Online':s.online===null?'미연동':'Offline'}</span><div class="server-metrics">${[['CPU',s.cpu],['RAM',s.ram],['DISK',s.disk]].map(([label,value])=>`<span>${label}<strong>${percent(value)}</strong><span class="mini-bar"><i style="width:${Math.max(0,Math.min(100,value||0))}%"></i></span></span>`).join('')}</div></div><div class="gpu-grid">${list.map(gpuCard).join('')}</div></section>`;}).join('')||'<div class="panel empty">조건에 맞는 GPU가 없습니다. 필터를 변경해보세요.</div>';}
function stats() {const g=snapshot.gpus,free=g.filter(x=>x.state==='FREE').length,borrow=g.filter(x=>x.state==='RESERVED_IDLE').length,busy=g.filter(x=>['RESERVED_IN_USE','UNRESERVED_IN_USE','BORROWED','CONFLICT'].includes(x.state)).length;const items=[['전체 GPU',g.length,'대','▦','',`${snapshot.servers.length}개의 워크스테이션`],['사용 가능',free,'대','◉','green','예약 없이 바로 사용 가능'],['사용 중',busy,'대','⌁','purple','현재 작업이 실행 중인 GPU'],['대여 가능',borrow,'대','⇄','orange','예약 중이지만 현재 유휴 상태']];return `<div class="stats">${items.map(([label,value,unit,icon,cls,note])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon ${cls}">${icon}</span></div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-note">${note}</div></div>`).join('')}</div>`;}
function filters() {return `<div class="filters"><select id="server-filter" aria-label="서버 필터"><option value="all">전체 워크스테이션</option>${snapshot.servers.map(s=>`<option value="${E(s.id)}" ${s.id===serverFilter?'selected':''}>${E(s.name)}</option>`).join('')}</select><select id="state-filter" aria-label="상태 필터"><option value="all">전체 상태</option>${Object.entries(states).map(([k,v])=>`<option value="${k}" ${k===stateFilter?'selected':''}>${v}</option>`).join('')}</select><div class="legend"><span>사용 가능</span><span class="busy">사용 중</span><span class="borrow">대여 중</span></div><input type="search" id="gpu-search" placeholder="GPU 또는 예약자 검색" aria-label="GPU 또는 예약자 검색" value="${E(query)}"></div>`;}
function reservationRows() {const rows=snapshot.reservations.filter(r=>new Date(r.end)>new Date()).sort((a,b)=>new Date(a.start)-new Date(b.start)).slice(0,4);return rows.map(r=>`<div class="reservation-row" role="button" tabindex="0" data-reservation="${E(r.id)}"><div class="reservation-time">${time(r.start)}<small>${date(r.start)}</small></div><span class="reservation-stripe"></span><div class="reservation-info"><strong>${E(r.title)}</strong><small>${E(r.resources.join(' + '))} · ${time(r.start)}–${time(r.end)}</small></div><span class="owner-pill">${E(r.owner_name||r.owner_linux)}</span></div>`).join('')||'<div class="empty">예정된 예약이 없습니다.</div>';}
const SERIES_COLORS=['#4e5be8','#e08a3c','#219780','#c0548f'];
function chart(series, colors=SERIES_COLORS) {if(!series.length||series.every(s=>!s.length))return `<div class="empty">${E(historyError||'사용률 이력이 없습니다.')}</div>`;const width=945,height=250;let out=`<svg viewBox="0 0 1000 300" role="img" aria-label="GPU 사용률 추이, 0에서 100퍼센트">`;for(let p=0;p<=100;p+=25){const y=20+height*(1-p/100);out+=`<line x1="48" y1="${y}" x2="1000" y2="${y}" stroke="#e9edf4" stroke-dasharray="4 6"/><text x="0" y="${y+6}" font-size="17" fill="#aab2c0">${p}</text>`;}const all=series.flat(),min=Math.min(...all.map(p=>p[0])),max=Math.max(...all.map(p=>p[0]));series.forEach((points,i)=>{if(!points.length)return;const xy=points.map(([t,v])=>`${55+(t-min)/(max-min||1)*width},${20+height*(1-Math.max(0,Math.min(100,v))/100)}`).join(' ');out+=`<polyline points="${xy}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"/>`;});return out+'</svg>';}
function serverSeries() {if(!history)return [];return snapshot.servers.map(s=>{const lists=snapshot.gpus.filter(g=>g.server===s.id).map(g=>history.series[g.id]||[]),byTime=new Map();lists.forEach(points=>points.forEach(([t,v])=>{const a=byTime.get(t)||[];a.push(v);byTime.set(t,a);}));return [...byTime].sort((a,b)=>a[0]-b[0]).map(([t,values])=>[t,values.reduce((a,b)=>a+b,0)/values.length]);});}
function trendPanel() {const series=serverSeries(),values=series.flat().map(p=>p[1]);const avg=values.length?values.reduce((a,b)=>a+b,0)/values.length:null;return `<div class="panel"><div class="section-head"><h2>GPU 사용률 추이 <small>최근 ${period===24?'24시간':'7일'}</small></h2><a class="text-link" href="#monitoring">자세히 보기 ↗</a></div><div class="chart-summary"><span><strong>${num(avg,1)}<small>%</small></strong> 평균 사용률</span><span>서버별 GPU 평균${snapshot.mode==='demo'?' · 예시 데이터':''}</span></div><div class="chart">${history?chart(series):`<div class="empty">${E(historyError||'그래프를 불러오는 중…')}</div>`}</div><div class="chart-labels"><span>${period===24?'24시간 전':'7일 전'}</span><span>${period===24?'12시간 전':'3.5일 전'}</span><span>현재</span></div><div class="chart-legend">${snapshot.servers.map((s,i)=>`<span><i style="background:${SERIES_COLORS[i%SERIES_COLORS.length]}"></i>${E(s.name)}</span>`).join('')}</div></div>`;}
function overview() {return `${stats()}<div class="section-head"><h2>워크스테이션 현황 <small>실시간 자원 모니터링</small></h2><div class="section-tools"><span class="meta"><span class="live-dot"></span>${REFRESH_LABEL} 업데이트</span><button class="button" id="refresh">↻ 새로고침</button></div></div>${filters()}<div id="server-list">${serverCards()}</div><div class="bottom-grid"><section class="panel"><div class="section-head"><h2>진행 중 · 다가오는 예약</h2><a class="text-link" href="#reservations">전체 보기 →</a></div>${reservationRows()}</section><div id="trend-panel">${trendPanel()}</div></div>`;}
function calendarPage() {const start=new Date(selectedDate+'T00:00:00+09:00').getTime(),end=start+86400000;const reservations=snapshot.reservations.filter(r=>new Date(r.start)<end&&new Date(r.end)>start);return `<section class="panel"><div class="section-head"><h2>일별 예약 일정 <small>${E(selectedDate)} · KST</small></h2><div class="date-nav"><button class="button" data-date-shift="-1" aria-label="전날">‹</button><input id="calendar-date" type="date" value="${E(selectedDate)}" aria-label="예약 날짜"><button class="button" data-date-shift="1" aria-label="다음 날">›</button><button class="button" id="calendar-today">오늘</button></div></div><div class="calendar"><div class="calendar-header"><span>GPU RESOURCE</span><div class="hours">${[0,3,6,9,12,15,18,21,24].map(h=>`<span>${String(h).padStart(2,'0')}:00</span>`).join('')}</div></div>${snapshot.gpus.map(g=>`<div class="calendar-row"><strong>${E(g.id)}</strong><div class="calendar-track">${reservations.filter(r=>r.resources.includes(g.id)).map(r=>{const left=(Math.max(start,new Date(r.start))-start)/86400000*100,width=(Math.min(end,new Date(r.end))-Math.max(start,new Date(r.start)))/86400000*100;return `<button class="calendar-event ${r.owner_linux===me()?.username?'':'other'}" data-reservation="${E(r.id)}" style="left:${left}%;width:${width}%" title="${E(r.title)} · ${E(r.owner_name)} ${time(r.start)}–${time(r.end)}">${E(r.title)}<small>${E(r.owner_name)} · ${time(r.start)}–${time(r.end)}</small></button>`;}).join('')}</div></div>`).join('')}</div><p class="form-intro">하나의 멀티 GPU 예약은 선택한 GPU의 각 행에 함께 표시됩니다. 예약을 클릭하면 상세 정보를 확인할 수 있습니다.</p></section><section class="panel" style="margin-top:20px"><div class="section-head"><h2>선택한 날짜의 예약 <small>${reservations.length}개</small></h2></div>${reservationTable(reservations)}</section>`;}
function reservationTable(rows) {return rows.length?`<div class="table-scroll"><table><thead><tr><th>작업 / 프로젝트</th><th>자원</th><th>예약자</th><th>예약 시간 (KST)</th><th>예상 자원</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.title)}<small>${E(r.project)}</small></td><td>${E(r.resources.join(', '))}</td><td>${E(r.owner_name||r.owner_linux)}</td><td>${date(r.start)} ${time(r.start)}<small>→ ${date(r.end)} ${time(r.end)}</small></td><td>${r.cpu_cores==null?'—':E(r.cpu_cores)+' cores'}<small>${r.ram_gb==null?'—':E(r.ram_gb)+' GB RAM'}</small></td><td><button class="button" data-reservation="${E(r.id)}">상세 보기</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">등록된 예약이 없습니다. 새 예약으로 다음 연구를 계획해보세요.</div>';}
function minePage() {if(snapshot.mode==='live')return `<section class="panel"><h2>내 예약 관리</h2><p class="form-intro">LibreBooking 계정으로 로그인하면 내 예약을 생성·수정·취소할 수 있습니다.</p><a class="button primary" href="${E(snapshot.links.booking)}" target="_blank" rel="noopener">LibreBooking 열기 ↗</a></section>`;const user=me();const rows=snapshot.reservations.filter(r=>r.owner_linux===user?.username);return `<section class="panel"><div class="section-head"><h2>${E(user?.display_name||'내')}님의 예약 <small>${E(user?.username||'')}${snapshot.mode==='demo'?' · 데모':''}</small></h2><span class="meta">${rows.length}개의 예약</span></div>${reservationTable(rows)}</section>`;}
function statisticsPanel() {return `<section class="panel" style="margin-top:20px"><div class="section-head"><h2>예약 대비 실사용 <small>최근 ${period===24?'24시간':'7일'} · ${snapshot.mode==='demo'?'예시 통계':'수집된 상태 기준'}</small></h2></div>${statistics?`<div class="table-scroll"><table><thead><tr><th>GPU</th><th>관측된 예약 시간</th><th>예약 중 사용 비율</th><th>수집률</th></tr></thead><tbody>${statistics.gpus.map(g=>`<tr><td>${E(g.id)}</td><td>${num(g.reserved_hours,1)} GPU-h</td><td>${percent(g.used_percent)}</td><td>${percent(g.coverage_percent)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${E(statisticsError||'통계를 불러오는 중…')}</div>`}<p class="form-intro">30초 간격으로 관측한 예약·Busy 상태를 집계합니다. 대여 사용도 포함하며, 오프라인·확인 불가 구간은 제외됩니다. 수집률이 낮으면 전체 기간을 대표하지 않습니다. 실제 통계는 연동 이후부터 쌓입니다.</p></section>`;}
function monitoringPage() {return `${stats()}<div class="section-head"><h2>사용률 기록</h2><div class="tabs"><button data-period="24" class="${period===24?'selected':''}">최근 24시간</button><button data-period="168" class="${period===168?'selected':''}">최근 7일</button></div></div><div id="monitor-trend">${trendPanel()}</div>${statisticsPanel()}<div class="monitor-cards">${snapshot.gpus.map(g=>{const points=history?.series[g.id]||[],avg=points.length?points.reduce((a,p)=>a+p[1],0)/points.length:null;return `<section class="panel"><div class="section-head"><h2>${E(g.id)} <small>${E(g.model)}</small></h2>${badge(g.state)}</div><div class="chart-summary"><span><strong>${num(avg,1)}%</strong>수집 구간 평균</span><span>현재 ${percent(g.metrics.util)}</span></div><div class="chart">${chart([points])}</div><div class="chart-labels"><span>${period===24?'24시간 전':'7일 전'}</span><span>현재</span></div></section>`;}).join('')}</div><p class="form-intro">그래프는 수집된 시점의 사용률입니다. 미수집 구간은 통계에서 제외됩니다. 장기 분석과 상세 서버 지표는 Grafana에서 확인하세요.</p><a class="button" href="${E(snapshot.links.grafana)}" target="_blank" rel="noopener">Grafana 상세 대시보드 ↗</a>`;}
function hourStrip(section) {const max=Math.max(1,...section.profile.map(p=>p.value||0));return `<div class="hour-strip">${section.profile.map(p=>`<span class="hour-cell ${p.value!=null&&p.value>=section.threshold_percent?'hot':''}" title="${p.hour}시 · ${p.value==null?'자료 없음':p.value+'%'}"><i style="height:${p.value==null?0:Math.max(6,p.value/max*100)}%"></i></span>`).join('')}</div><div class="hour-axis"><span>00시</span><span>06시</span><span>12시</span><span>18시</span><span>23시</span></div>`;}
function saturationCard(server) {return `<section class="panel"><div class="section-head"><h2>${E(server.name)} <small>${E(server.id)} · 시간대별 평균</small></h2></div>${[['CPU',server.cpu],['RAM',server.ram]].map(([label,section])=>`<div class="meter-label"><span>${label} 포화 ${section.threshold_percent}% 이상 ${num(section.saturated_hours,1)}시간</span><b>${section.peak_hour==null?'—':String(section.peak_hour).padStart(2,'0')+'시 최고'}</b></div>${hourStrip(section)}`).join('')}<div class="report-legend"><span><i></i>시간대 평균</span><span><i class="hot"></i>포화 ${server.cpu.threshold_percent}% 이상</span></div></section>`;}
function reportsPage() {const tabs=`<div class="tabs">${[[7,'최근 7일'],[30,'최근 30일']].map(([d,label])=>`<button data-report-days="${d}" class="${reportDays===d?'selected':''}">${label}</button>`).join('')}</div>`;
  if(!report)return `<div class="section-head"><h2>운영 리포트</h2>${tabs}</div><div class="panel empty">${E(reportError||'리포트를 불러오는 중…')}</div>`;
  const gpus=report.gpus,sum=key=>gpus.reduce((a,g)=>a+(g[key]||0),0),observed=gpus.filter(g=>g.avg_util!=null);
  const r=report.reservations,users=report.users;
  const cards=[['평균 GPU 사용률',observed.length?num(observed.reduce((a,g)=>a+g.avg_util,0)/observed.length,1):'—','%','⌁','purple',`${report.days}일 관측 평균`],
    ['실사용 시간',num(sum('busy_hours')),'GPU-h','◉','green','프로세스·VRAM 기준 Busy 합계'],
    ['유휴 시간',num(sum('idle_hours')),'GPU-h','◇','','관측된 구간 중 idle 합계'],
    ['멀티 GPU 예약',r.multi_gpu_percent==null?'—':num(r.multi_gpu_percent),'%','⇄','orange',`${r.total}건 중 ${r.multi_gpu}건`]];
  const servers=snapshot.servers.map(s=>{const list=gpus.filter(g=>g.server===s.id);return {name:s.name,id:s.id,idle:list.reduce((a,g)=>a+(g.idle_hours||0),0),busy:list.reduce((a,g)=>a+(g.busy_hours||0),0)};});
  const maxUser=Math.max(1,...users.map(u=>Math.max(u.used_gpu_hours||0,u.reserved_gpu_hours||0)));
  return `<div class="section-head"><h2>기간 요약 <small>${report.mode==='demo'?'예시 데이터':'수집된 기록'} · ${E(date(report.generated_at))} 기준</small></h2>${tabs}</div>
<div class="stats">${cards.map(([label,value,unit,icon,cls,note])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon ${cls}">${icon}</span></div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-note">${note}</div></div>`).join('')}</div>
<section class="panel"><div class="section-head"><h2>GPU별 사용 기록 <small>최근 ${report.days}일</small></h2></div><div class="table-scroll"><table><thead><tr><th>GPU</th><th>평균 사용률</th><th>실사용</th><th>유휴</th><th>예약</th><th>예약 중 사용</th><th>수집률</th></tr></thead><tbody>${gpus.map(g=>`<tr><td>${E(g.id)}<small>${E(g.server)}</small></td><td>${percent(g.avg_util)}</td><td>${num(g.busy_hours,1)} h</td><td>${num(g.idle_hours,1)} h</td><td>${num(g.reserved_hours,1)} h</td><td>${percent(g.reserved_busy_percent)}</td><td>${percent(g.coverage_percent)}</td></tr>`).join('')}</tbody></table></div><p class="form-intro">실사용은 프로세스·VRAM·사용률로 판정한 Busy 시간이며 대여 사용도 포함합니다. 수집률은 관측된 표본 비율입니다. 확인되지 않은 구간은 유휴로 계산하지 않습니다.</p></section>
<div class="report-cards"><section class="panel"><div class="section-head"><h2>서버별 GPU 시간 <small>유휴 / 실사용</small></h2></div>${servers.map(s=>`<div class="meter-label"><span>${E(s.name)}</span><b>유휴 ${num(s.idle,1)} h · 실사용 ${num(s.busy,1)} h</b></div><div class="bar"><i style="width:${s.busy+s.idle?s.busy/(s.busy+s.idle)*100:0}%"></i></div>`).join('')}<p class="form-intro">유휴 시간이 길고 예약 충돌이 적다면 증설보다 사용 시간 조정이 먼저입니다.</p></section>
<section class="panel"><div class="section-head"><h2>학생별 GPU-hour <small>예약 대비 실사용</small></h2></div>${users.length?users.map(u=>`<div class="meter-label"><span>${E(u.name||u.user)}</span><b>실사용 ${u.used_gpu_hours==null?'—':num(u.used_gpu_hours,1)+' h'} · 예약 ${num(u.reserved_gpu_hours,1)} h</b></div><div class="usage-bar"><i style="width:${Math.min(100,(u.used_gpu_hours||0)/maxUser*100)}%"></i></div><div class="usage-bar"><i class="reserved" style="width:${Math.min(100,(u.reserved_gpu_hours||0)/maxUser*100)}%"></i></div>`).join(''):'<div class="empty">집계할 예약·사용 기록이 없습니다.</div>'}<p class="form-intro">위 막대가 실사용, 아래가 예약 시간입니다. 실사용 GPU-hour는 프로세스 수집기가 확인한 Linux 사용자 기준입니다.</p></section></div>
<div class="report-cards">${report.servers.map(saturationCard).join('')}</div>
<section class="panel" style="margin-top:20px"><div class="section-head"><h2>리포트 해석 <small>운영 판단 기준</small></h2></div><div class="reservation-row"><span class="owner-pill">멀티 GPU</span><span style="font-size:11px;color:#8d96a5">${r.total}건 중 ${r.multi_gpu}건이 여러 GPU를 함께 예약했습니다. 평균 예약 길이는 ${r.average_hours==null?'—':num(r.average_hours,1)+'시간'}, 총 예약은 ${num(r.reserved_gpu_hours,1)} GPU-h입니다.</span></div><div class="reservation-row"><span class="owner-pill">보관 기간</span><span style="font-size:11px;color:#8d96a5">Prometheus 보관 기간(${report.retention_days}일)과 포털 연동 시작 시점 이전 구간은 집계되지 않습니다. 수집률이 낮은 GPU는 전체 기간을 대표하지 않습니다.</span></div><div class="reservation-row"><span class="owner-pill">사용 목적</span><span style="font-size:11px;color:#8d96a5">이 통계는 학생 평가가 아니라 서버 증설·재배치 판단에 사용합니다.${report.mode==='demo'?' 현재 값은 데모 예시입니다.':''}</span></div></section>
<a class="button" href="${E(snapshot.links.grafana)}" target="_blank" rel="noopener">Grafana 장기 대시보드 ↗</a>`;}
function bytes(value) {if(value==null||!Number.isFinite(+value))return '—';const units=['B','KB','MB','GB','TB','PB'];let n=+value,i=0;while(n>=1024&&i<units.length-1){n/=1024;i++;}return `${n.toFixed(n>=100||i<2?0:1)} ${units[i]}`;}
function storagePage() {
  if(!storage)return `<div class="panel empty">${E(storageError||'저장공간 정보를 불러오는 중…')}</div>`;
  const palette=['#5961df','#8b63cc','#219780','#dc9843','#4a93c9','#c96a8f','#6f7b8c'];
  const all=storage.servers.flatMap(s=>s.disks||[]);
  const shared=storage.shared||[];
  const every=[...all,...shared];
  const total=every.reduce((a,d)=>a+(d.total||0),0),used=every.reduce((a,d)=>a+(d.used||0),0);
  const byUser={};all.forEach(d=>(d.users||[]).forEach(u=>{byUser[u.display]=(byUser[u.display]||0)+u.bytes;}));
  const top=Object.entries(byUser).sort((a,b)=>b[1]-a[1])[0];
  const summary=[['전체 용량',bytes(total),'','▧','',`디스크 ${all.length}개 · 공유 ${shared.length}개`],
    ['사용 중',bytes(used),'','⌁','purple',total?`${(used/total*100).toFixed(0)}% 사용`:''],
    ['남은 용량',bytes(total-used),'','◉','green',total?`${((total-used)/total*100).toFixed(0)}% 여유`:''],
    ['가장 많이 쓰는 사람',top?top[0]:'—','','◇','orange',top?bytes(top[1]):'측정된 폴더 없음']];
  return `<div class="stats">${summary.map(([label,value,unit,icon,cls,note])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon ${cls}">${icon}</span></div><div class="stat-value" style="font-size:24px">${E(value)}<small>${unit}</small></div><div class="stat-note">${E(note)}</div></div>`).join('')}</div>`+
  storage.servers.map(server=>{
    const disks=server.disks||[];
    if(!disks.length)return `<section class="panel" style="margin-bottom:20px"><div class="section-head"><h2>${E(server.name)}</h2></div><div class="empty">측정된 디스크가 없습니다. 서버에서 setup_storage.sh를 실행하세요.</div></section>`;
    return `<section class="panel" style="margin-bottom:20px"><div class="section-head"><h2>${E(server.name)} <small>${E(server.id)}</small></h2><span class="meta">${disks.length}개 디스크${server.measured_at?' · '+time(server.measured_at*1000)+' 측정':''}</span></div>
    ${disks.map(disk=>{const used=disk.used||0,total=disk.total||0,pct=total?used/total*100:0;
      const people=(disk.users||[]).filter(u=>u.bytes>0&&!u.system);const sum=people.reduce((a,u)=>a+u.bytes,0);
      return `<div class="disk"><div class="disk-head"><strong>${E(disk.mount)}</strong><span>${bytes(used)} / ${bytes(total)} 사용 <b class="${pct>=85?'hot':''}">${pct.toFixed(0)}%</b></span></div>
      <div class="stack">${people.map((u,i)=>`<i style="width:${total?u.bytes/total*100:0}%;background:${palette[i%palette.length]}" title="${E(u.display)} ${bytes(u.bytes)}"></i>`).join('')}<i class="rest" style="width:${total?Math.max(0,(used-sum))/total*100:0}%"></i></div>
      ${people.length?`<div class="legend-rows">${people.map((u,i)=>`<span><i style="background:${palette[i%palette.length]}"></i>${E(u.display)}${u.claimed?'':' <small>미연결</small>'}<b>${bytes(u.bytes)}</b></span>`).join('')}</div>`:'<p class="form-intro">사용자 폴더가 없습니다.</p>'}</div>`;}).join('')}</section>`;}).join('')+
    shared.map(disk=>{const used=disk.used||0,total=disk.total||0,pct=total?used/total*100:0;
    return `<section class="panel" style="margin-bottom:20px"><div class="section-head"><h2>${E(disk.name)} <small>공유 저장소 · ${E(disk.mount)}</small></h2><span class="meta">${(disk.servers||[]).join(', ')}에서 연결</span></div>
    <div class="disk-head"><strong>전체 용량</strong><span>${bytes(used)} / ${bytes(total)} 사용 <b class="${pct>=85?'hot':''}">${pct.toFixed(0)}%</b></span></div>
    <div class="stack"><i style="width:${pct}%;background:#5961df"></i></div>
    <p class="form-intro">네트워크 공유라 폴더별 사용량은 측정하지 않습니다.</p></section>`;}).join('')+
  `<p class="form-intro">30분마다 측정합니다. 폴더 이름은 워크스테이션 로그인 계정이며, <a class="text-link" href="#accounts">계정 연결</a>을 하면 한글 이름으로 보입니다.</p>`;
}
function accountsPage() {
  const me=me_();
  const members=(accounts&&accounts.members)||[];
  const list=accounts?accounts.servers:[];
  return `<section class="panel"><div class="section-head"><h2>내 워크스테이션 계정 <small>한 번만 연결하면 됩니다</small></h2></div>
  <p class="form-intro">서버에서 쓰는 로그인 계정(예: <code>kiyeong</code>)을 지금 로그인한 계정(${E(me?.display_name||'내 계정')})에 연결하면, 사용량·저장공간 어디서나 한글 이름 하나로 묶여서 보입니다.</p>
  ${accountsError?`<div class="empty">${E(accountsError)}</div>`:!accounts?'<div class="empty">워크스테이션 계정을 확인하는 중…</div>':list.map(server=>`<div class="account-server"><h3>${E(server.name)}</h3>${server.accounts.length?`<div class="account-chips">${server.accounts.map(a=>`<button class="chip ${a.mine?'mine':a.claimed_by?'taken':''}" ${a.claimed_by&&!a.mine?'disabled':''} data-claim="${E(server.id)}|${E(a.linux_username)}" data-mine="${a.mine?'1':''}">${E(a.linux_username)}${a.claimed_by?`<small>${a.mine?'내 계정 · 해제':E(a.claimed_by)}</small>`:'<small>내 계정으로 연결</small>'}</button>`).join('')}</div>`:'<p class="form-intro">아직 이 서버에서 확인된 계정이 없습니다. 한 번이라도 GPU를 쓰거나 저장공간을 쓰면 나타납니다.</p>'}</div>`).join('')}
  </section>
  <section class="panel" style="margin-top:20px"><div class="section-head"><h2>연구실 구성원 <small>${members.length}명 가입</small></h2></div>
  ${members.length?`<div class="table-scroll"><table><thead><tr><th>이름</th><th>포털 아이디</th><th>연결된 서버 계정</th>${accounts&&accounts.can_manage?'<th></th>':''}</tr></thead><tbody>${members.map(m=>`<tr><td><strong>${E(m.display_name)}</strong>${m.role==='admin'?' <span class="owner-pill">관리자</span>':''}</td><td><code>${E(m.username)}</code></td><td>${m.linux.length?m.linux.map(E).join(', '):'<span style="color:#a6afbf">연결 안 함</span>'}</td>${accounts&&accounts.can_manage?`<td>${m.username===me_()?.username?'':`<button class="button danger-button" data-remove-member="${E(m.username)}">삭제</button>`}</td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">구성원 정보를 불러오는 중…</div>'}</section>`;
}
function newsCard(item,ci,ii) {return `<button class="news-card" data-news="${ci}|${ii}">${item.image?`<img loading="lazy" src="/api/news/image?u=${encodeURIComponent(item.image)}" alt="">`:'<span class="news-thumb">📰</span>'}<strong>${E(item.title)}</strong><small>${E(item.source)}</small></button>`;}
function newsRegion_() {return (news&&news.regions.find(r=>r.id===newsRegion))||(news&&news.regions[0]);}
function newsPage() {
  if(!news)return `<div class="panel empty">${E(newsError||'뉴스를 불러오는 중…')}</div>`;
  const region=newsRegion_();
  return `<div class="section-head"><h2>최신 소식</h2><div class="tabs">${news.regions.map(r=>`<button data-news-region="${E(r.id)}" class="${r.id===region.id?'selected':''}">${E(r.name)}</button>`).join('')}</div></div>`+
  region.categories.map((c,ci)=>`<section class="panel news-row" style="margin-bottom:20px"><div class="section-head"><h2>${E(c.name)} <small>${E(c.note)}</small></h2><span class="meta">${c.items.length}건 · 좌우로 끌어보세요</span></div><div class="news-track" data-track>${c.items.map((item,ii)=>newsCard(item,ci,ii)).join('')||'<div class="empty">기사가 없습니다.</div>'}</div></section>`).join('')+
  `<p class="form-intro">30분마다 새로 가져옵니다. 카드를 누르면 창 안에서 크게 보고, 좌우로 넘길 수 있습니다.</p>`;
}
function showNews(ci,ii) {
  const category=(newsRegion_()||{categories:[]}).categories[ci];if(!category)return;const item=category.items[ii];if(!item)return;
  newsOpen={ci,ii};
  $('#detail-content').innerHTML=`<div class="dialog-head"><h2 id="detail-title">${E(category.name)}</h2>${closeButton()}</div>
  <article class="news-view">${item.image?`<img src="/api/news/image?u=${encodeURIComponent(item.image)}" alt="">`:''}
  <h3>${E(item.title)}</h3><p class="news-meta">${E(item.source)}${item.published?' · '+E(item.published):''}</p>
  <p class="news-body">${E(item.summary||'요약이 제공되지 않는 기사입니다.')}</p></article>
  <div class="dialog-actions news-actions"><button class="button" data-news-step="-1" ${ii===0?'disabled':''}>← 이전</button><span class="news-count">${ii+1} / ${category.items.length}</span><button class="button" data-news-step="1" ${ii===category.items.length-1?'disabled':''}>다음 →</button><a class="button primary" href="${E(item.link)}" target="_blank" rel="noopener">원문 열기 ↗</a></div>`;
  if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
}
function guidePage() {const rules=[['01','예약은 우선권입니다','예약은 해당 시간에 GPU를 우선 사용할 약속입니다. Linux·CUDA 접근을 차단하거나 예약 종료 시 프로세스를 종료하지 않습니다.'],['02','비어 있다면 함께 사용해요','예약된 GPU라도 프로세스가 없고 VRAM과 최근 사용률이 낮으면 임시 사용이 가능합니다. 원 예약자가 요청하면 합리적인 시간 내에 비워주세요.'],['03','실험 계획을 공유해주세요','프로젝트, 작업 유형, 예상 CPU·RAM을 기록하세요. 48시간이 넘는 작업에는 장기 사용 사유를 남겨주세요. CPU·RAM 입력은 참고 정보입니다.'],['04','계획이 바뀌면 예약도 변경해요','작업이 일찍 끝나면 예약을 축소하거나 취소하세요. 여러 GPU가 필요하면 하나의 예약에서 함께 선택하세요.'],['05','사용 중인 사람과 먼저 이야기해요','예약자와 실사용자가 다를 수 있습니다. 대여 중 또는 조정 필요 상태는 사용자 간 확인이 필요하며, 시스템이 작업을 중단하지 않습니다.'],['06','확인되지 않은 상태는 확인부터','오프라인이나 확인 필요 표시는 사용 가능하다는 뜻이 아닙니다. 수집기, 네트워크 또는 예약 서비스 연결을 먼저 확인하세요.']];return `<div class="guide-grid">${rules.map(([n,title,text])=>`<section class="guide-card"><span class="number">${n} / LAB ETIQUETTE</span><h3>${title}</h3><p>${text}</p></section>`).join('')}</div><section class="panel" style="margin-top:20px"><div class="section-head"><h2>상태 표시 알아보기</h2></div>${Object.entries(states).map(([k])=>`<div class="reservation-row">${badge(k)}<span style="font-size:11px;color:#8d96a5">${stateHelp[k]}</span></div>`).join('')}</section>`;}
const BACKSLASH = String.fromCharCode(92);
function codeBlock(lines) {return `<pre class="code-block">${lines.map(E).join(String.fromCharCode(10))}</pre>`;}
function remotePage() {const servers=[['iGDSL-Aurora','10.174.52.127','RTX PRO 6000 Blackwell × 4 (96 GB)','Ubuntu 26.04'],['iGDSL-Polaris','10.174.52.130','RTX A6000 × 2 (48 GB)','Ubuntu 24.04']];
  const steps=[
    ['01','계정 만들기 (관리자에게 요청)','아직 서버 계정이 없다면 관리자에게 아이디를 알려주고 만들어 달라고 하세요. 관리자는 서버에서 아래를 실행합니다. 두 워크스테이션 모두에서 각각 만들어야 합니다.',
     ['sudo adduser 사용자이름','# 필요하면 관리자 권한도','sudo usermod -aG sudo 사용자이름']],
    ['02','Windows에서 접속하기','시작 메뉴에서 PowerShell을 열고 아래를 입력합니다. 처음 접속하면 확인 메시지가 나오는데 yes를 입력한 뒤 비밀번호를 칩니다. 비밀번호는 화면에 보이지 않는 것이 정상입니다.',
     ['ssh 사용자이름@10.174.52.127   # Aurora','ssh 사용자이름@10.174.52.130   # Polaris']],
    ['03','VS Code로 연결 (권장)','VS Code에서 Remote - SSH 확장을 설치합니다. Ctrl+Shift+P → Remote-SSH: Open SSH Configuration File 을 실행하고, 본인 계정 폴더의 .ssh 안에 있는 config 파일을 고릅니다. 아래 내용을 붙여넣고 저장하세요.',
     ['# 파일 위치: C:' + BACKSLASH + 'Users' + BACKSLASH + '본인계정' + BACKSLASH + '.ssh' + BACKSLASH + 'config','','Host Aurora','    HostName 10.174.52.127','    User 사용자이름','    Port 22','','Host Polaris','    HostName 10.174.52.130','    User 사용자이름','    Port 22']],
    ['04','VS Code에서 서버 열기','Ctrl+Shift+P → Remote-SSH: Connect to Host → Aurora 또는 Polaris를 고릅니다. 처음이면 플랫폼은 Linux를 선택하고 비밀번호를 입력합니다. 왼쪽 아래에 SSH: Aurora 가 보이면 연결된 것입니다. File → Open Folder로 작업 폴더를 엽니다.',
     ['mkdir -p ~/workspace','# File → Open Folder → /home/사용자이름/workspace']],
    ['05','개발 환경 준비','처음 한 번만 실행합니다. Conda가 없다면 Miniconda를 본인 계정에 설치하고 프로젝트마다 가상환경을 따로 만들어 쓰세요.',
     ['sudo apt update','sudo apt install -y git wget curl tmux htop unzip zip','conda create -n myproject python=3.11','conda activate myproject']],
    ['06','GPU 확인하고 쓰기','접속한 뒤 지금 GPU가 비어 있는지 확인합니다. 특정 GPU만 쓰려면 CUDA_VISIBLE_DEVICES로 번호를 지정합니다. 번호는 이 사이트의 GPU 카드 이름 끝자리와 같습니다.',
     ['nvidia-smi','watch -n 2 nvidia-smi','CUDA_VISIBLE_DEVICES=0 python train.py']],
  ];
  return `<section class="panel"><div class="section-head"><h2>연구실 워크스테이션 <small>둘 다 같은 방법으로 접속합니다</small></h2></div><div class="table-scroll"><table><thead><tr><th>이름</th><th>주소</th><th>GPU</th><th>OS</th></tr></thead><tbody>${servers.map(([name,ip,gpu,os])=>`<tr><td><strong>${E(name)}</strong></td><td><code>${E(ip)}</code></td><td>${E(gpu)}</td><td>${E(os)}</td></tr>`).join('')}</tbody></table></div><p class="form-intro">연구실 네트워크(또는 학교 VPN) 안에서만 접속됩니다. 사용자 이름과 비밀번호는 각자 다르며, 관리자가 만들어 준 계정을 씁니다.</p></section>
<div class="guide-grid" style="margin-top:20px">${steps.map(([n,title,text,lines])=>`<section class="guide-card"><span class="number">${n} / REMOTE ACCESS</span><h3>${E(title)}</h3><p>${E(text)}</p>${codeBlock(lines)}</section>`).join('')}</div>
<section class="panel" style="margin-top:20px"><div class="section-head"><h2>함께 쓸 때의 약속</h2></div><div class="reservation-row"><span class="owner-pill">예약</span><span style="font-size:11px;color:#8d96a5">긴 학습이나 여러 장을 쓸 계획이면 이 사이트에서 먼저 예약하세요. 예약이 없어도 GPU는 쓸 수 있지만, 예약자가 우선입니다.</span></div><div class="reservation-row"><span class="owner-pill">확인</span><span style="font-size:11px;color:#8d96a5">시작 전에 대시보드에서 비어 있는 GPU를 고르고, <code>CUDA_VISIBLE_DEVICES</code>로 그 번호만 쓰세요. 다른 사람 작업을 종료하지 마세요.</span></div><div class="reservation-row"><span class="owner-pill">정리</span><span style="font-size:11px;color:#8d96a5">작업이 끝나면 프로세스를 종료하고, 예약이 남았으면 취소하거나 시간을 줄여 주세요.</span></div><a class="button" href="#guide" style="margin-top:14px">이용 가이드 보기 →</a></section>`;}
function render() {if(!snapshot)return;page=(location.hash.slice(1)||'overview');if(!titles[page])page='overview';const [title,crumb]=titles[page];$('#page-title').textContent=title;$('#crumb').textContent=crumb;$$('nav [data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#mode-badge').textContent={demo:'DEMO WORKSPACE',standalone:'LAB WORKSPACE',live:'LIVE WORKSPACE'}[snapshot.mode]||'WORKSPACE';
  const banner=$('#demo-banner');
  if(snapshot.mode==='demo')banner.innerHTML='<span>◈</span><div><strong>데모 워크스페이스</strong><span> 예시 장비·사용량입니다. 예약을 직접 만들어볼 수 있으며 실제 GPU에는 영향을 주지 않습니다.</span></div><a href="#remote">접속 안내 ↗</a>';
  else if(snapshot.notice)banner.innerHTML=`<span>◈</span><div><strong>모니터링 미연동</strong><span> ${E(snapshot.notice)}</span></div><a href="#remote">접속 안내 ↗</a>`;
  banner.hidden=snapshot.mode!=='demo'&&!snapshot.notice;
  const user=me();
  $('#profile-name').innerHTML=user?`${E(user.display_name)}<small>${E(user.username)}${user.role==='admin'?' · 관리자':''}</small>`:'연구실 포털<small>예약 관리는 LibreBooking</small>';
  $('#profile-avatar').textContent=user?(user.display_name||user.username).trim().charAt(0):'·';
  $('#logout-button').hidden=!(session&&session.requires_login&&user);
  $('#new-reservation').hidden=!['overview','reservations'].includes(page);const views={overview,reservations:calendarPage,mine:minePage,monitoring:monitoringPage,storage:storagePage,reports:reportsPage,guide:guidePage,remote:remotePage,accounts:accountsPage,news:newsPage};$('#content').innerHTML=views[page]();$('#refresh-status').textContent=`${time(snapshot.updated_at)} 업데이트 · ${REFRESH_LABEL} 자동 갱신`;const alerts=snapshot.alerts||[];$('#alert-dot').hidden=!alerts.length;$('#alert-dot').className=alerts.some(a=>a.level==='danger')?'danger':'';$('#notification-button').setAttribute('aria-label',alerts.length?`상태 알림 ${alerts.length}건 보기`:'상태 알림 보기');}
async function loadHistory(){if(snapshot&&snapshot.monitoring===false){history=null;statistics=null;historyError=statisticsError=NO_MONITORING;if(page==='overview'&&$('#trend-panel'))$('#trend-panel').innerHTML=trendPanel();if(page==='monitoring')render();return;}const key=++historyKey;const results=await Promise.allSettled([api(`/api/history?hours=${period}`),api(`/api/statistics?hours=${period}`)]);if(key!==historyKey)return;history=results[0].status==='fulfilled'?results[0].value:null;historyError=results[0].status==='rejected'?results[0].reason.message:'';statistics=results[1].status==='fulfilled'?results[1].value:null;statisticsError=results[1].status==='rejected'?results[1].reason.message:'';if(page==='overview'&&$('#trend-panel'))$('#trend-panel').innerHTML=trendPanel();if(page==='monitoring')render();}
async function loadStorage(){if(snapshot&&snapshot.monitoring===false){storage=null;storageError=NO_MONITORING;if(page==='storage')render();return;}try{storage=await api('/api/storage');storageError='';}catch(e){storage=null;storageError=e.message;}if(page==='storage')render();}
async function loadAccounts(){try{const [list,members]=await Promise.all([api('/api/linux-accounts'),api('/api/members')]);accounts={...list,can_manage:!!members.can_manage,members:(members.members||[]).map(m=>({...m,linux:[]}))};
  const claimed={};list.servers.forEach(sv=>sv.accounts.forEach(a=>{if(a.claimed_by)(claimed[a.claimed_by]=claimed[a.claimed_by]||[]).push(a.linux_username);}));
  accounts.members.forEach(m=>{m.linux=[...new Set(claimed[m.display_name]||[])];});accountsError='';}catch(e){accounts=null;accountsError=e.message;}if(page==='accounts')render();}
async function loadNews(){try{news=await api('/api/news');newsError='';}catch(e){news=null;newsError=e.message;}if(page==='news')render();}
async function loadReport(){if(snapshot&&snapshot.monitoring===false){report=null;reportError=NO_MONITORING;if(page==='reports')render();return;}const key=++reportKey;try{const data=await api(`/api/reports?days=${reportDays}`);if(key!==reportKey)return;report=data;reportError='';}catch(e){if(key!==reportKey)return;report=null;reportError=e.message;}if(page==='reports')render();}
async function refresh(initial=false){if(refreshBusy)return;refreshBusy=true;try{snapshot=await api('/api/snapshot');$('#connection-error').hidden=!snapshot.errors.length;$('#connection-error').textContent=snapshot.errors.join(' ');const busy=$('#reservation-dialog').open||$('#detail-dialog').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName);if(initial||!busy)render();if(initial){await loadHistory();loadForPage();}}catch(e){if(e.status===401){signedOut();return;}$('#connection-error').hidden=false;$('#connection-error').textContent=`연결 실패: ${e.message} ${snapshot?'아래는 마지막으로 수신한 정보입니다.':'서버 실행 상태를 확인하세요.'}`;if(!snapshot)$('#content').innerHTML='<div class="panel empty">데이터를 불러오지 못했습니다. 연결 복구 후 자동으로 다시 시도합니다.</div>';}finally{refreshBusy=false;}}
function openForm(id=null,resource=null){if(!snapshot)return;if(snapshot.mode==='live'){window.open(snapshot.links.booking,'_blank','noopener');return;}const form=$('#reservation-form');form.reset();form.elements.id.value=id||'';const r=id?snapshot.reservations.find(r=>r.id===id):null;$('#dialog-title').textContent=r?'예약 수정':'새 GPU 예약';const owner=me();$('#form-owner').textContent=owner?`${owner.display_name} (${owner.username})님의 우선 사용 시간을 등록합니다.`:'우선 사용 시간을 등록합니다.';$('#form-error').textContent='';$('#gpu-options').innerHTML=snapshot.gpus.map(g=>`<label><input type="checkbox" name="resources" value="${E(g.id)}" ${(r?.resources.includes(g.id)||g.id===resource)?'checked':''}>${E(g.id)}</label>`).join('');const start=new Date(Math.ceil(Date.now()/1800000)*1800000);form.elements.start.value=kstInput(r?new Date(r.start):start);form.elements.end.value=kstInput(r?new Date(r.end):new Date(start.getTime()+2*3600000));if(r)['title','project','cpu_cores','ram_gb','job_type','note'].forEach(k=>form.elements[k].value=r[k]??'');$('#detail-dialog').close();$('#reservation-dialog').showModal();}
function closeButton(){return '<button class="icon-button close-detail" aria-label="닫기">✕</button>';}
function showReservation(id){const r=snapshot.reservations.find(r=>r.id===id);if(!r)return;$('#detail-content').innerHTML=`<div class="dialog-head"><h2 id="detail-title">${E(r.title)}</h2>${closeButton()}</div><p class="form-intro">${E(r.project)}</p><div class="detail-block"><p>예약자<strong>${E(r.owner_name)} · ${E(r.owner_linux||'계정 매핑 없음')}</strong></p><p>GPU<strong>${E(r.resources.join(', '))}</strong></p><p>시작<strong>${date(r.start)} ${time(r.start)} KST</strong></p><p>종료<strong>${date(r.end)} ${time(r.end)} KST</strong></p><p>예상 자원<strong>${num(r.cpu_cores)} cores · ${num(r.ram_gb)} GB RAM</strong></p><p>작업 유형<strong>${E(r.job_type||'—')}</strong></p></div><p class="detail-note">${E(r.note||'등록된 메모가 없습니다.')}</p><div class="form-error" id="detail-error" role="alert"></div><div class="dialog-actions">${canManage(r)?`<button class="button danger-button" data-cancel="${E(r.id)}">예약 취소</button><button class="button primary" data-edit="${E(r.id)}">예약 수정</button>`:snapshot.mode==='live'?`<a class="button primary" href="${E(snapshot.links.booking)}" target="_blank" rel="noopener">LibreBooking에서 관리 ↗</a>`:'<button class="button close-detail">닫기</button>'}</div>`;$('#detail-dialog').showModal();}
function showGPU(id){const g=snapshot.gpus.find(g=>g.id===id),m=g.metrics;$('#detail-content').innerHTML=`<div class="dialog-head"><h2 id="detail-title">${E(g.id)}</h2>${closeButton()}</div><p class="form-intro">${E(g.model)} · ${E(g.vram_gb)} GB · ${E(g.server)}</p>${badge(g.state)}<p class="detail-note">${E(stateNote(g.state))}</p><div class="detail-block"><p>현재 사용률<strong>${percent(m.util)}</strong></p><p>최근 10분 평균<strong>${percent(m.util_avg)}</strong></p><p>VRAM 사용량<strong>${num(m.vram_used_mib==null?null:m.vram_used_mib/1024,1)} GB</strong></p><p>온도 / 전력<strong>${num(m.temperature)}°C / ${num(m.power)} W</strong></p><p>현재 예약자<strong>${E(g.reservation?.owner_name||'없음 / 확인 필요')}</strong></p></div><h3 style="font-size:13px">실행 중인 Compute 프로세스</h3>${m.processes===null||m.processes===undefined?'<p class="detail-note">프로세스 수집 정보가 없습니다.</p>':m.processes.length?`<div class="table-scroll"><table><thead><tr><th>Linux 사용자</th><th>PID</th><th>VRAM</th></tr></thead><tbody>${m.processes.map(p=>`<tr><td>${E(p.user)}</td><td>${E(p.pid)}</td><td>${p.memory_mib==null?'—':num(p.memory_mib)+' MiB'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="detail-note">실행 중인 Compute 프로세스가 없습니다.</p>'}<p class="form-intro">상태는 참고 정보입니다. 실제 GPU 접근을 제어하지 않습니다.</p><div class="dialog-actions"><button class="button primary" data-book-gpu="${E(g.id)}">이 GPU 예약하기</button></div>`;$('#detail-dialog').showModal();}
function showAlerts(){if(!snapshot)return;const alerts=snapshot.alerts||[];$('#detail-content').innerHTML=`<div class="dialog-head"><h2 id="detail-title">워크스페이스 알림</h2>${closeButton()}</div><p class="form-intro">현재 상태를 바탕으로 표시하는 참고 알림입니다. 알림은 작업을 중단하거나 GPU 권한을 바꾸지 않습니다.</p>${alerts.map(a=>`<div class="alert-item ${a.level==='danger'?'danger':a.level==='info'?'info':''}"><strong>${a.resource?E(a.resource)+' · ':''}${E(a.title)}</strong><p>${E(a.message)}</p></div>`).join('')||'<div class="empty">확인이 필요한 알림이 없습니다.</div>'}`;$('#detail-dialog').showModal();}
document.addEventListener('click',async event=>{const target=event.target.closest('button,[data-reservation]');if(!target)return;if(target.classList.contains('close-dialog'))$('#reservation-dialog').close();if(target.classList.contains('close-detail')){newsOpen=null;$('#detail-dialog').close();}if(target.id==='new-reservation')openForm();if(target.id==='notification-button')showAlerts();if(target.id==='refresh'){target.disabled=true;await refresh();await loadHistory();toast('최신 상태를 확인했습니다.');}if(target.dataset.gpu)showGPU(target.dataset.gpu);if(target.dataset.reservation)showReservation(target.dataset.reservation);if(target.dataset.bookGpu)openForm(null,target.dataset.bookGpu);if(target.dataset.edit)openForm(target.dataset.edit);if(target.dataset.cancel){if(!target.dataset.confirmed){target.dataset.confirmed='yes';target.textContent='정말 취소할까요?';return;}target.disabled=true;try{await api(`/api/reservations/${encodeURIComponent(target.dataset.cancel)}`,{method:'DELETE'});$('#detail-dialog').close();await refresh();render();toast('예약을 취소했습니다.');}catch(e){$('#detail-error').textContent=e.message;target.disabled=false;}}if(target.dataset.dateShift){selectedDate=kstDate(new Date(new Date(selectedDate+'T00:00:00+09:00').getTime()+Number(target.dataset.dateShift)*86400000));render();}if(target.id==='calendar-today'){selectedDate=kstDate(new Date());render();}if(target.dataset.period){period=Number(target.dataset.period);history=null;render();loadHistory();}if(target.dataset.reportDays){reportDays=Number(target.dataset.reportDays);report=null;render();loadReport();}
  if(target.dataset.claim){const [server,linux]=target.dataset.claim.split('|');target.disabled=true;
    try{if(target.dataset.mine){await api(`/api/linux-accounts?server=${encodeURIComponent(server)}&linux_username=${encodeURIComponent(linux)}`,{method:'DELETE'});toast('연결을 해제했습니다.');}
      else{await api('/api/linux-accounts',{method:'POST',body:JSON.stringify({server,linux_username:linux})});toast(`${linux} 계정을 연결했습니다.`);}
      await loadAccounts();storage=null;await refresh();if(page==='accounts')render();}
    catch(e){toast(e.message);target.disabled=false;}}
  if(target.dataset.removeMember){const name=target.dataset.removeMember;
    if(!target.dataset.confirmed){target.dataset.confirmed='yes';target.textContent='정말 삭제할까요?';return;}
    target.disabled=true;
    try{await api(`/api/members?username=${encodeURIComponent(name)}`,{method:'DELETE'});toast(`${name} 계정을 삭제했습니다.`);await loadAccounts();render();}
    catch(e){toast(e.message);target.disabled=false;}}
  if(target.dataset.newsRegion){newsRegion=target.dataset.newsRegion;render();}
  if(target.dataset.news){const [ci,ii]=target.dataset.news.split('|').map(Number);showNews(ci,ii);}
  if(target.dataset.newsStep&&newsOpen){showNews(newsOpen.ci,newsOpen.ii+Number(target.dataset.newsStep));}});
document.addEventListener('error',event=>{const img=event.target;if(!(img instanceof HTMLImageElement)||!img.closest('.news-card,.news-view'))return;
  const mark=document.createElement('span');mark.className='news-thumb';mark.textContent='📰';img.replaceWith(mark);},true);
// 뉴스 카드 줄을 마우스로 끌어서 넘깁니다.
document.addEventListener('pointerdown',event=>{const track=event.target.closest('[data-track]');if(!track||event.button!==0)return;
  const startX=event.clientX,startLeft=track.scrollLeft;let moved=false;
  const move=e=>{const dx=e.clientX-startX;if(Math.abs(dx)>4){moved=true;track.classList.add('dragging');}track.scrollLeft=startLeft-dx;};
  const up=e=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);track.classList.remove('dragging');
    if(moved){e.preventDefault();const block=ev=>{ev.stopPropagation();ev.preventDefault();};track.addEventListener('click',block,{capture:true,once:true});setTimeout(()=>track.removeEventListener('click',block,true),0);}};
  document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);});
document.addEventListener('keydown',event=>{if(!newsOpen||!$('#detail-dialog').open)return;
  if(event.key==='ArrowRight'){event.preventDefault();showNews(newsOpen.ci,newsOpen.ii+1);}
  if(event.key==='ArrowLeft'){event.preventDefault();showNews(newsOpen.ci,newsOpen.ii-1);}});
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('.reservation-row[data-reservation]')){event.preventDefault();showReservation(event.target.dataset.reservation);}});
document.addEventListener('change',e=>{if(e.target.id==='server-filter'){serverFilter=e.target.value;$('#server-list').innerHTML=serverCards();}if(e.target.id==='state-filter'){stateFilter=e.target.value;$('#server-list').innerHTML=serverCards();}if(e.target.id==='calendar-date'&&e.target.value){selectedDate=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='gpu-search'){query=e.target.value;$('#server-list').innerHTML=serverCards();}});
$('#reservation-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form)),id=data.id;delete data.id;data.resources=new FormData(form).getAll('resources');if(!data.resources.length){$('#form-error').textContent='GPU를 하나 이상 선택하세요.';return;}data.start=new Date(data.start+':00+09:00').toISOString();data.end=new Date(data.end+':00+09:00').toISOString();data.cpu_cores=Number(data.cpu_cores);data.ram_gb=Number(data.ram_gb);const button=$('button[type=submit]',form);button.disabled=true;$('#form-error').textContent='';try{await api(`/api/reservations${id?'/'+encodeURIComponent(id):''}`,{method:id?'PUT':'POST',body:JSON.stringify(data)});$('#reservation-dialog').close();await refresh();render();toast(id?'예약을 수정했습니다.':'새 예약이 등록되었습니다.');}catch(error){$('#form-error').textContent=error.message;}finally{button.disabled=false;}});
function loadForPage(){if(page==='monitoring')loadHistory();if(page==='reports'&&!report)loadReport();if(page==='storage'&&!storage)loadStorage();if(page==='accounts')loadAccounts();if(page==='news'&&!news)loadNews();}
window.addEventListener('hashchange',()=>{if(!snapshot)return;render();loadForPage();});
function authed(){return !session||!session.requires_login||session.authenticated;}
function signedOut(){session={...session,authenticated:false,user:null,first_account:false};snapshot=null;history=report=statistics=null;$('#auth-title').textContent='iGDSL GPU 예약';$('#auth-subtitle').textContent='계정으로 로그인하면 GPU 예약과 실시간 사용 현황을 확인할 수 있습니다.';setAuthTab('login');showAuth();}
function showAuth(){$('#auth-screen').hidden=false;document.body.classList.add('signed-out');const form=authTab==='login'?$('#login-form'):$('#signup-form');form.elements.username.focus();}
function hideAuth(){$('#auth-screen').hidden=true;document.body.classList.remove('signed-out');}
function setAuthTab(tab){authTab=tab;$$('[data-auth-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.authTab===tab));$('#login-form').hidden=tab!=='login';$('#signup-form').hidden=tab!=='signup';}
async function submitAuth(form,path,errorId){const data=Object.fromEntries(new FormData(form));const button=$('button[type=submit]',form);button.disabled=true;$(errorId).textContent='';try{const user=await api(path,{method:'POST',body:JSON.stringify(data)});session={...session,authenticated:true,user,first_account:false};form.reset();hideAuth();await refresh(true);toast(`${user.display_name}님, 환영합니다.`);}catch(error){$(errorId).textContent=error.message;}finally{button.disabled=false;}}
$('#login-form').addEventListener('submit',e=>{e.preventDefault();submitAuth(e.target,'/api/auth/login','#login-error');});
$('#signup-form').addEventListener('submit',e=>{e.preventDefault();submitAuth(e.target,'/api/auth/signup','#signup-error');});
document.addEventListener('click',async event=>{const tab=event.target.closest('[data-auth-tab]');if(tab)setAuthTab(tab.dataset.authTab);
  if(event.target.closest('#logout-button')){try{await api('/api/auth/logout',{method:'POST'});}catch{}$('#content').innerHTML='<div class="loading">로그인이 필요합니다.</div>';signedOut();}});
async function boot(){
  try{session=await api('/api/session');}catch{session={mode:'standalone',requires_login:true,authenticated:false,first_account:false};}
  if(session.first_account)setAuthTab('signup');
  if(!authed()){showAuth();return;}
  hideAuth();await refresh(true);
}
boot();
setInterval(()=>{if(!document.hidden&&authed())refresh();},REFRESH_MS);
setInterval(()=>{if(!document.hidden&&authed()&&['overview','monitoring'].includes(page))loadHistory();if(!document.hidden&&authed()&&page==='reports')loadReport();},TREND_MS);
// Coming back to the tab should show current numbers immediately.
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&authed()&&snapshot)refresh();});
